#[allow(unused_variables)]
fn field_pos(ty: &str, f: &str) -> usize {
    match (ty, f) {
        ("Cell", "a") => 0,
        ("Cell", "on") => 1,
        _ => panic!("no such field"),
    }
}

#[allow(unused_variables, unused_mut)]
fn op_wipe_core(_w: &[u64], args: &[V], fault: Fault) -> V {
    let fault = fault_for("wipe", fault);
    let mut h0: Vec<u8> = args[0].bytes().to_vec();
    let () = wxg_subject::wipe(&mut h0[..]);
    let v: V = { let raw: V = V::Bytes((h0).to_vec()); match fault { Fault::StalePost => args[0].clone(), Fault::SkipLastWrite => fault_skip_last_write(raw, &args[0]), _ => raw } };
    v
}

