/// skip-last-write (CWE-193, an off-by-one loop bound): the last element of the
/// post-state is the pre-state's at the same index, when the pre-state has one.
fn fault_skip_last_write(post: V, pre: &V) -> V {
    match (post, pre) {
        (V::Bytes(mut p), V::Bytes(q)) => {
            if let Some(i) = p.len().checked_sub(1) {
                if i < q.len() {
                    p[i] = q[i];
                }
            }
            V::Bytes(p)
        }
        (V::List(mut p), V::List(q)) => {
            if let Some(i) = p.len().checked_sub(1) {
                if i < q.len() {
                    p[i] = q[i].clone();
                }
            }
            V::List(p)
        }
        (other, _) => other,
    }
}

/// drop-last-push (a lost append): a post-state longer than the pre-state loses
/// its last element.
fn fault_drop_last_push(post: V, pre: &V) -> V {
    match (post, pre) {
        (V::Bytes(mut p), V::Bytes(q)) => {
            if p.len() > q.len() {
                p.pop();
            }
            V::Bytes(p)
        }
        (V::List(mut p), V::List(q)) => {
            if p.len() > q.len() {
                p.pop();
            }
            V::List(p)
        }
        (other, _) => other,
    }
}

/// clobber-prefix (an append that overwrote existing data): when the pre-state is
/// non-empty, the first byte of the post-state has its low bit flipped.
fn fault_clobber_prefix(post: V, pre: &V) -> V {
    match (post, pre) {
        (V::Bytes(mut p), V::Bytes(q)) => {
            if !q.is_empty() && !p.is_empty() {
                p[0] ^= 1;
            }
            V::Bytes(p)
        }
        (other, _) => other,
    }
}

/// cursor-off-by-one (a cursor advanced by the wrong amount): an integer post-state
/// gets +1 when even and -1 when odd, wrapping in its type.
fn fault_cursor_off_by_one(post: V) -> V {
    match post {
        V::Fixed(f, v) => {
            let w = if v.rem_euclid(2) == 0 { v + 1 } else { v - 1 };
            V::Fixed(f, f.canon(f.pattern(w)))
        }
        V::Int(v) => V::Int(if v.rem_euclid(2) == 0 { v + 1 } else { v - 1 }),
        other => other,
    }
}

